package org.apache.commons.math3.geometry.euclidean.threed;

import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_9_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Create a line with two distinct points
        Vector3D p1 = new Vector3D(0, 0, 0);
        Vector3D p2 = new Vector3D(1, 0, 0);
        Line line = new Line(p1, p2);

        // Revert the line
        Line revertedLine = line.revert();

        // The direction of the reverted line should be the negation of the original direction
        Vector3D originalDirection = line.getDirection();
        Vector3D revertedDirection = revertedLine.getDirection();

        // Assert that the direction is correctly negated
        assertEquals("The X component of the direction should be negated.",
                     -originalDirection.getX(), revertedDirection.getX(), 1e-10);
        assertEquals("The Y component of the direction should be negated.",
                     -originalDirection.getY(), revertedDirection.getY(), 1e-10);
        assertEquals("The Z component of the direction should be negated.",
                     -originalDirection.getZ(), revertedDirection.getZ(), 1e-10);
    }
}

