package org.apache.commons.math3.geometry.euclidean.threed;

import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_9_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Create a line with a specific direction
        Vector3D direction = new Vector3D(1, 0, 0);
        Vector3D point = new Vector3D(0, 0, 0);
        Line line = new Line(point, direction);

        // Revert the line
        Line revertedLine = line.revert();

        // The direction of the reverted line should be the negation of the original direction
        Vector3D expectedRevertedDirection = direction.negate();
        Vector3D actualRevertedDirection = revertedLine.getDirection();

        // Assert that the direction is correctly negated
        assertEquals("The direction of the reverted line should be the negation of the original direction.",
                     expectedRevertedDirection, actualRevertedDirection);
    }
}

